loginUrl:
function getHost() { return 'https://www.ppxsw.cc'; }

function refreshCaptcha() {
    var url = getHost() + '/code.jpg?' + Math.random();
    java.startBrowser(url, '验证码');
}

function login(b) {
    if (b == undefined) return true;
    var info = result;
    var user = info['账号'];
    var pass = info['密码'];
    var code = info['验证码'];
    if (!user || !pass || !code) {
        java.toast('请完整填写账号、密码和验证码');
        return;
    }
    var body = 'user_name=' + encodeURIComponent(user) + '&user_pass=' + java.md5Encode(pass) + '&user_code=' + encodeURIComponent(code);
    var post = JSON.stringify({
        method: 'POST',
        body: body,
        headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
            'Referer': 'https://www.ppxsw.cc/login.html',
            'X-Requested-With': 'XMLHttpRequest'
        }
    });
    var resp = String(java.ajax(getHost() + '/qs_login_go.php,' + post));
    if (resp.indexOf('1|') >= 0) {
        var ck = java.getCookie(getHost());
        if (ck) {
            source.putLoginHeader(ck);
        }
        java.toast('皮皮小说·登录成功');
    } else {
        java.toast('登录失败：' + resp);
        refreshCaptcha();
    }
}

function logout() {
    source.removeLoginHeader();
    cookie.removeCookie(getHost());
    result['账号'] = '';
    result['密码'] = '';
    result['验证码'] = '';
    source.putLoginInfo(JSON.stringify(result));
    java.toast('已登出');
}
